import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Kernel 日报 2026-11-02","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/02.md","filePath":"notes/kernel-digest/2026/11/02.md"}'),n={name:"notes/kernel-digest/2026/11/02.md"};function l(i,e,s,c,p,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-02" tabindex="-1">Kernel 日报 2026-11-02 <a class="header-anchor" href="#kernel-日报-2026-11-02" aria-label="Permalink to &quot;Kernel 日报 2026-11-02&quot;">​</a></h1><blockquote><p>生成时间：2026-11-02T01:38:12Z｜共 69 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-02 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_5c97d8672a5b-·-remote-code-execution-on-linux-systems-with-multipath-tcp" tabindex="-1"><code>5c97d8672a5b</code> · <a href="https://lwn.net/Articles/1104192/" target="_blank" rel="noreferrer">Remote code execution on Linux systems with multipath TCP</a> <a class="header-anchor" href="#_5c97d8672a5b-·-remote-code-execution-on-linux-systems-with-multipath-tcp" aria-label="Permalink to &quot;`5c97d8672a5b` · [Remote code execution on Linux systems with multipath TCP](https://lwn.net/Articles/1104192/)&quot;">​</a></h3><p><em>daroc｜lwn｜网络</em></p><p>Anthropic 报告了一个影响开启 multipath TCP 监听的系统的远程可利用 use-after-free 漏洞：重传 SYN 包的响应与另一线程建立 TCP 连接的时序竞争，导致访问已被释放的连接 options 结构，可泄露内核内存或触发缓冲区溢出。修复方案是在 RCU grace period 之后才释放该结构。</p><blockquote><p><strong>学习价值</strong>：是典型的内核并发竞态漏洞分析案例，展示了 RCU 在修复 use-after-free 中的实际应用，非常适合网络子系统学习者研读。</p></blockquote><h3 id="c261aaa452f3-·-removing-binder-c" tabindex="-1"><code>c261aaa452f3</code> · <a href="https://lwn.net/Articles/1102982/" target="_blank" rel="noreferrer">[$] Removing binder.c</a> <a class="header-anchor" href="#c261aaa452f3-·-removing-binder-c" aria-label="Permalink to &quot;`c261aaa452f3` · [[$] Removing binder.c](https://lwn.net/Articles/1102982/)&quot;">​</a></h3><p><em>daroc｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>在 Kangrejos 2026 大会上，Carlos Llamas 宣布删除了 Android Binder 驱动的 C 语言实现，Binder 是 Android 的核心进程间通信机制。Alice Ryhl 补充介绍了用 Rust 实现替换 C 实现过程中最困难和有趣的部分。</p><blockquote><p><strong>学习价值</strong>：是 Linux 内核中大型 C 驱动迁移到 Rust 的标志性案例，对关注 Rust in Linux 的学习者极具参考价值。</p></blockquote><h3 id="ae6464ee11ce-·-the-linux-7-4-merge-window-is-easily-the-largest-in-kernel-history" tabindex="-1"><code>ae6464ee11ce</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Massive-Window" target="_blank" rel="noreferrer">The Linux 7.4 Merge Window Is Easily The Largest In Kernel History</a> <a class="header-anchor" href="#ae6464ee11ce-·-the-linux-7-4-merge-window-is-easily-the-largest-in-kernel-history" aria-label="Permalink to &quot;`ae6464ee11ce` · [The Linux 7.4 Merge Window Is Easily The Largest In Kernel History](https://www.phoronix.com/news/Linux-7.4-Massive-Window)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 7.4 的 merge window 成为内核历史上规模最大的一次，文章通过与过去 15 年各主要版本的对比数据加以说明。作者指出近期提交量的明显上升可能与 AI/LLM 辅助开发活动的增加有关。</p><blockquote><p><strong>学习价值</strong>：从宏观统计视角观察内核开发节奏与 AI 对开发流程的影响，有助于理解社区演进趋势。</p></blockquote><h3 id="_8e91cf16d1c7-·-patch-v1-0-2-hrtimer-add-hrtimer-forward-safe-from-callback" tabindex="-1"><code>8e91cf16d1c7</code> · <a href="https://lore.kernel.org/all/20261101232829.593680-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1 0/2] hrtimer: Add hrtimer_forward_safe_from_callback()</a> <a class="header-anchor" href="#_8e91cf16d1c7-·-patch-v1-0-2-hrtimer-add-hrtimer-forward-safe-from-callback" aria-label="Permalink to &quot;`8e91cf16d1c7` · [[PATCH v1 0/2] hrtimer: Add hrtimer_forward_safe_from_callback()](https://lore.kernel.org/all/20261101232829.593680-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux｜Rust in Linux</em></p><p>补丁系列封面：由于 safe Rust 代码可在回调运行期间重新启动定时器，Rust 抽象无法将 hrtimer_forward() 作为安全 API 提供给回调使用。按 Thomas Gleixner 的建议新增一个在 base lock 下完成检查与更新的辅助函数（patch 1），并让 Rust 回调上下文改用它（patch 2）。该辅助函数并非 Rust 专用，i915_pmu 和 null_blk 也可受益。</p><blockquote><p><strong>学习价值</strong>：说明 Rust 抽象的需求如何反哺 C 核心代码改进，体现了两个语言生态协作演进的典型路径。</p></blockquote><h3 id="_6c2ffc1dec26-·-patch-net-15-15-netfilter-nat-zero-newrange-before-filling-it-in" tabindex="-1"><code>6c2ffc1dec26</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-16-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 15/15] netfilter: nat: zero newrange before filling it in</a> <a class="header-anchor" href="#_6c2ffc1dec26-·-patch-net-15-15-netfilter-nat-zero-newrange-before-filling-it-in" aria-label="Permalink to &quot;`6c2ffc1dec26` · [[PATCH net 15/15] netfilter: nat: zero newrange before filling it in](https://lore.kernel.org/all/20261102005654.532438-16-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev｜网络</em></p><p>修复 netfilter NAT 中多个函数（nf_nat_masquerade_ipv4/ipv6、netmap_tg4/tg6）构造栈上 struct nf_nat_range2 时未完全清零的问题，导致 base_proto 残留栈垃圾。当继承的 flags 包含 NF_NAT_RANGE_PROTO_OFFSET 时，nf_nat_l4proto_unique_tuple() 会读取垃圾值计算 NAT 端口偏移。修复方式是在填充前先 memset 整个 newrange。</p><blockquote><p><strong>学习价值</strong>：展示了未初始化栈变量如何通过 flags 继承路径演变为可利用的内核信息泄露/逻辑漏洞，是学习安全审计的好案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（2 条）</li><li><strong>网络</strong>（15 条）</li><li><strong>文件系统与存储</strong>（2 条）</li><li><strong>Rust in Linux</strong>（12 条）</li><li><strong>跟踪与性能</strong>（6 条）</li><li><strong>版本发布动态</strong>（9 条）</li><li><strong>其他动态</strong>（23 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="e4f49f7abd5c-·-damon-release-newsletter-for-v7-4-rc1" tabindex="-1"><code>e4f49f7abd5c</code> · <a href="https://lore.kernel.org/all/20261101235500.102023-1-sj@kernel.org/" target="_blank" rel="noreferrer">DAMON Release Newsletter for v7.4-rc1</a> <a class="header-anchor" href="#e4f49f7abd5c-·-damon-release-newsletter-for-v7-4-rc1" aria-label="Permalink to &quot;`e4f49f7abd5c` · [DAMON Release Newsletter for v7.4-rc1](https://lore.kernel.org/all/20261101235500.102023-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>SJ Park 发布 DAMON v7.4-rc1 周期简报：23 位作者贡献 159 个 commit、约 3260 行改动，是 DAMON 历史上作者数最多的周期之一。本期合入 7 个新特性以及多项重要优化和修复。</p><blockquote><p><strong>学习价值</strong>：跟踪 DAMON（数据访问监控）子系统的官方渠道，适合了解内存监控技术的发展脉络和社区协作模式。</p></blockquote><h3 id="b540e3edce55-·-kernel-liveupdate-luo-file-c-558-5-13-error-invalid-reference-to-the-index-variable-of-the-iterator-on-line-553-fwd" tabindex="-1"><code>b540e3edce55</code> · <a href="https://lore.kernel.org/all/a1b79e2b-e960-b6de-9139-fbbd13bfb2b3@inria.fr/" target="_blank" rel="noreferrer">kernel/liveupdate/luo_file.c:558:5-13: ERROR: invalid reference to the index variable of the iterator on line 553 (fwd)</a> <a class="header-anchor" href="#b540e3edce55-·-kernel-liveupdate-luo-file-c-558-5-13-error-invalid-reference-to-the-index-variable-of-the-iterator-on-line-553-fwd" aria-label="Permalink to &quot;`b540e3edce55` · [kernel/liveupdate/luo_file.c:558:5-13: ERROR: invalid reference to the index variable of the iterator on line 553 (fwd)](https://lore.kernel.org/all/a1b79e2b-e960-b6de-9139-fbbd13bfb2b3@inria.fr/)&quot;">​</a></h3><p><em>Julia Lawall (<a href="mailto:julia.lawall@inria.fr" target="_blank" rel="noreferrer">julia.lawall@inria.fr</a>)｜linux-mm</em></p><p>静态检查发现 liveupdate（LUO）子系统的 luo_file.c 中，list_for_each_entry 循环若从未执行 break，循环后使用的迭代变量 luo_file 可能指向随机内存。Julia Lawall 转发该报告并指出这一典型的迭代器变量误用问题。</p><blockquote><p><strong>学习价值</strong>：经典的 list_for_each_entry 迭代变量越界使用案例，对学习内核链表遍历的正确写法很有警示价值。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_5c97d8672a5b-·-remote-code-execution-on-linux-systems-with-multipath-tcp-1" tabindex="-1"><code>5c97d8672a5b</code> · <a href="https://lwn.net/Articles/1104192/" target="_blank" rel="noreferrer">Remote code execution on Linux systems with multipath TCP</a> <a class="header-anchor" href="#_5c97d8672a5b-·-remote-code-execution-on-linux-systems-with-multipath-tcp-1" aria-label="Permalink to &quot;`5c97d8672a5b` · [Remote code execution on Linux systems with multipath TCP](https://lwn.net/Articles/1104192/)&quot;">​</a></h3><p><em>daroc｜lwn</em></p><p>Anthropic 报告了一个影响开启 multipath TCP 监听的系统的远程可利用 use-after-free 漏洞：重传 SYN 包的响应与另一线程建立 TCP 连接的时序竞争，导致访问已被释放的连接 options 结构，可泄露内核内存或触发缓冲区溢出。修复方案是在 RCU grace period 之后才释放该结构。</p><blockquote><p><strong>学习价值</strong>：是典型的内核并发竞态漏洞分析案例，展示了 RCU 在修复 use-after-free 中的实际应用，非常适合网络子系统学习者研读。</p></blockquote><h3 id="_4dbc1054473f-·-patch-rfc-v2-3-4-selftests-bpf-add-negative-test-for-sockmap-update-from-non-sockmap-iter" tabindex="-1"><code>4dbc1054473f</code> · <a href="https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-3-e96a63c43b39@rbox.co/" target="_blank" rel="noreferrer">[PATCH RFC v2 3/4] selftests/bpf: Add negative test for sockmap update from non-sockmap iter</a> <a class="header-anchor" href="#_4dbc1054473f-·-patch-rfc-v2-3-4-selftests-bpf-add-negative-test-for-sockmap-update-from-non-sockmap-iter" aria-label="Permalink to &quot;`4dbc1054473f` · [[PATCH RFC v2 3/4] selftests/bpf: Add negative test for sockmap update from non-sockmap iter](https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-3-e96a63c43b39@rbox.co/)&quot;">​</a></h3><p><em>Michal Luczaj (<a href="mailto:mhal@rbox.co" target="_blank" rel="noreferrer">mhal@rbox.co</a>)｜netdev</em></p><p>配合 iter-context sockmap 更新限制的收紧，新增负向测试：从 iter/unix 迭代器中尝试更新 sockmap 并预期被 verifier 拒绝。测试添加在 selftests/bpf 的 verifier_sockmap_mutate.c 中。</p><blockquote><p><strong>学习价值</strong>：示范了如何为 BPF verifier 新限制编写负向测试，是学习 BPF 自测体系的好材料。</p></blockquote><h3 id="_9adf4cc52f26-·-patch-rfc-v2-2-4-bpf-sockmap-restrict-iter-context-sockmap-updates-to-iter-sockmap" tabindex="-1"><code>9adf4cc52f26</code> · <a href="https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-2-e96a63c43b39@rbox.co/" target="_blank" rel="noreferrer">[PATCH RFC v2 2/4] bpf, sockmap: Restrict iter-context sockmap updates to iter/sockmap</a> <a class="header-anchor" href="#_9adf4cc52f26-·-patch-rfc-v2-2-4-bpf-sockmap-restrict-iter-context-sockmap-updates-to-iter-sockmap" aria-label="Permalink to &quot;`9adf4cc52f26` · [[PATCH RFC v2 2/4] bpf, sockmap: Restrict iter-context sockmap updates to iter/sockmap](https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-2-e96a63c43b39@rbox.co/)&quot;">​</a></h3><p><em>Michal Luczaj (<a href="mailto:mhal@rbox.co" target="_blank" rel="noreferrer">mhal@rbox.co</a>)｜netdev</em></p><p>该补丁将 tracing 程序中对 sockmap/sockhash 的更新权限收紧到仅 iter/sockmap 迭代器，此前任意 BPF_TRACE_ITER 程序都可执行更新并在特定场景（如 af_unix iter）引发死锁和锁问题。这是 BPF API lockdown 整体工作的一部分。</p><blockquote><p><strong>学习价值</strong>：揭示了 BPF 迭代器上下文中跨 map 操作的锁顺序陷阱，对理解 sockmap 内部锁机制很有价值。</p></blockquote><h3 id="_1ca97b954131-·-patch-rfc-v2-1-4-selftests-bpf-remove-sockmap-update-from-bpf-iter-unix" tabindex="-1"><code>1ca97b954131</code> · <a href="https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-1-e96a63c43b39@rbox.co/" target="_blank" rel="noreferrer">[PATCH RFC v2 1/4] selftests/bpf: Remove sockmap update from bpf_iter_unix</a> <a class="header-anchor" href="#_1ca97b954131-·-patch-rfc-v2-1-4-selftests-bpf-remove-sockmap-update-from-bpf-iter-unix" aria-label="Permalink to &quot;`1ca97b954131` · [[PATCH RFC v2 1/4] selftests/bpf: Remove sockmap update from bpf_iter_unix](https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-1-e96a63c43b39@rbox.co/)&quot;">​</a></h3><p><em>Michal Luczaj (<a href="mailto:mhal@rbox.co" target="_blank" rel="noreferrer">mhal@rbox.co</a>)｜netdev</em></p><p>由于 sockmap 更新即将被限制为仅 iter/sockmap 可执行，该补丁从 bpf_iter_unix 自测程序中移除相关更新代码，实际是 revert 了此前用于复现死锁的 commit 997b8483d44c。</p><blockquote><p><strong>学习价值</strong>：展示了 API 收紧时自测代码的同步清理流程，体现补丁系列间的依赖关系。</p></blockquote><h3 id="d38850802e9b-·-patch-rfc-v2-0-4-bpf-sockmap-restrict-iter-context-sockmap-updates-to-sockmap-iterators" tabindex="-1"><code>d38850802e9b</code> · <a href="https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-0-e96a63c43b39@rbox.co/" target="_blank" rel="noreferrer">[PATCH RFC v2 0/4] bpf, sockmap: Restrict iter-context sockmap updates to sockmap iterators</a> <a class="header-anchor" href="#d38850802e9b-·-patch-rfc-v2-0-4-bpf-sockmap-restrict-iter-context-sockmap-updates-to-sockmap-iterators" aria-label="Permalink to &quot;`d38850802e9b` · [[PATCH RFC v2 0/4] bpf, sockmap: Restrict iter-context sockmap updates to sockmap iterators](https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-0-e96a63c43b39@rbox.co/)&quot;">​</a></h3><p><em>Michal Luczaj (<a href="mailto:mhal@rbox.co" target="_blank" rel="noreferrer">mhal@rbox.co</a>)｜netdev</em></p><p>本系列四补丁响应 Sashiko 的报告，将 iter-context 的 sockmap 更新限制为仅 iter/sockmap：包括移除将失效的旧测试、实施限制、添加负向测试，并将 bpf_iter__sockmap::sk 标记为 PTR_TRUSTED。v2 还处理了 BPF 程序扩展与迭代器目标程序的交互问题。</p><blockquote><p><strong>学习价值</strong>：一个完整的 BPF API 安全收紧系列范本，展示从问题报告、设计决策到测试配套的全流程。</p></blockquote><h3 id="_6c2ffc1dec26-·-patch-net-15-15-netfilter-nat-zero-newrange-before-filling-it-in-1" tabindex="-1"><code>6c2ffc1dec26</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-16-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 15/15] netfilter: nat: zero newrange before filling it in</a> <a class="header-anchor" href="#_6c2ffc1dec26-·-patch-net-15-15-netfilter-nat-zero-newrange-before-filling-it-in-1" aria-label="Permalink to &quot;`6c2ffc1dec26` · [[PATCH net 15/15] netfilter: nat: zero newrange before filling it in](https://lore.kernel.org/all/20261102005654.532438-16-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 netfilter NAT 中多个函数（nf_nat_masquerade_ipv4/ipv6、netmap_tg4/tg6）构造栈上 struct nf_nat_range2 时未完全清零的问题，导致 base_proto 残留栈垃圾。当继承的 flags 包含 NF_NAT_RANGE_PROTO_OFFSET 时，nf_nat_l4proto_unique_tuple() 会读取垃圾值计算 NAT 端口偏移。修复方式是在填充前先 memset 整个 newrange。</p><blockquote><p><strong>学习价值</strong>：展示了未初始化栈变量如何通过 flags 继承路径演变为可利用的内核信息泄露/逻辑漏洞，是学习安全审计的好案例。</p></blockquote><h3 id="ca873d51d430-·-patch-net-14-15-netfilter-xt-recent-do-not-call-remove-proc-entry-under-recent-lock" tabindex="-1"><code>ca873d51d430</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-15-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 14/15] netfilter: xt_recent: do not call remove_proc_entry() under recent_lock</a> <a class="header-anchor" href="#ca873d51d430-·-patch-net-14-15-netfilter-xt-recent-do-not-call-remove-proc-entry-under-recent-lock" aria-label="Permalink to &quot;`ca873d51d430` · [[PATCH net 14/15] netfilter: xt_recent: do not call remove_proc_entry() under recent_lock](https://lore.kernel.org/all/20261102005654.532438-15-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 xt_recent 中 recent_proc_net_exit() 在持有 spin_lock_bh(&amp;recent_lock) 的情况下调用 remove_proc_entry() 的问题。由于 remove_proc_entry() 可能睡眠（等待 proc 文件操作中的读者退出），网络命名空间销毁时 cleanup_net() 会在原子上下文睡眠并死锁。修复是将 remove_proc_entry() 移出锁保护。</p><blockquote><p><strong>学习价值</strong>：经典的 &quot;sleep in atomic context&quot; 死锁案例，帮助理解 procfs 文件生命周期与自旋锁的交互。</p></blockquote><h3 id="_8473b1a32d75-·-patch-net-13-15-netfilter-nf-tables-fix-memleak-when-rule-deletion-fails-with-hardware-offload" tabindex="-1"><code>8473b1a32d75</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-14-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 13/15] netfilter: nf_tables: fix memleak when rule deletion fails with hardware offload</a> <a class="header-anchor" href="#_8473b1a32d75-·-patch-net-13-15-netfilter-nf-tables-fix-memleak-when-rule-deletion-fails-with-hardware-offload" aria-label="Permalink to &quot;`8473b1a32d75` · [[PATCH net 13/15] netfilter: nf_tables: fix memleak when rule deletion fails with hardware offload](https://lore.kernel.org/all/20261102005654.532438-14-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 nf_tables 硬件 offload 场景下规则删除失败时的内存泄漏：将 flow rule 对象的分配移到事务分配和规则去激活之后，让事务 abort 路径负责回滚已有的去激活操作。同时更新 nft_flow_rule_destroy() 以在 flow_rule 为 NULL 时跳过释放。</p><blockquote><p><strong>学习价值</strong>：展示了 nf_tables 事务模型与 offload 错误路径的资源管理，是理解事务回滚设计的实用参考。</p></blockquote><h3 id="_74f90f4ae023-·-patch-net-12-15-netfilter-nf-conntrack-sip-fix-oob-read-in-ct-sip-parse-transport" tabindex="-1"><code>74f90f4ae023</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-13-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 12/15] netfilter: nf_conntrack_sip: fix OOB read in ct_sip_parse_transport()</a> <a class="header-anchor" href="#_74f90f4ae023-·-patch-net-12-15-netfilter-nf-conntrack-sip-fix-oob-read-in-ct-sip-parse-transport" aria-label="Permalink to &quot;`74f90f4ae023` · [[PATCH net 12/15] netfilter: nf_conntrack_sip: fix OOB read in ct_sip_parse_transport()](https://lore.kernel.org/all/20261102005654.532438-13-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 nf_conntrack_sip 中 ct_sip_parse_transport() 的越界读取：该函数用 strncasecmp(..., 3) 比较 &quot;transport=&quot; 参数值与 &quot;TCP&quot;/&quot;UDP&quot;，但未检查解析值是否至少 3 字节长。当值只有 1-2 字节且恰好位于 payload 末尾时（如 Contact 头以 &quot;;transport=T&quot; 结尾），会读到缓冲区之外。</p><blockquote><p><strong>学习价值</strong>：典型的长度校验缺失导致的 OOB read，提醒学习者在解析网络报文时必须先验证长度再比较内容。</p></blockquote><h3 id="ea156e77d4f3-·-patch-net-11-15-netfilter-x-tables-check-target-name-before-accessing-verdict" tabindex="-1"><code>ea156e77d4f3</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-12-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 11/15] netfilter: x_tables: check target name before accessing verdict</a> <a class="header-anchor" href="#ea156e77d4f3-·-patch-net-11-15-netfilter-x-tables-check-target-name-before-accessing-verdict" aria-label="Permalink to &quot;`ea156e77d4f3` · [[PATCH net 11/15] netfilter: x_tables: check target name before accessing verdict](https://lore.kernel.org/all/20261102005654.532438-12-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 x_tables 中 mark_source_chains() 在检查 target 名称之前就按 xt_standard_target 读取 verdict 的问题。非标准 target 可能只包含 struct xt_entry_target，导致读取越界 4 字节（KASAN 报告 slab-out-of-bounds）。修复为先确认是标准 target 再读 verdict，非标准 target 仍按 fallthrough 处理。</p><blockquote><p><strong>学习价值</strong>：演示了 KASAN 如何捕获类型混淆式越界读，以及 iptables 规则校验路径的内部结构。</p></blockquote><h3 id="a459f1d9af42-·-patch-net-10-15-netfilter-bridge-use-debug-net-warn-on-once-in-nf-ct-bridge-refrag" tabindex="-1"><code>a459f1d9af42</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-11-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 10/15] netfilter: bridge: use DEBUG_NET_WARN_ON_ONCE in nf_ct_bridge_refrag()</a> <a class="header-anchor" href="#a459f1d9af42-·-patch-net-10-15-netfilter-bridge-use-debug-net-warn-on-once-in-nf-ct-bridge-refrag" aria-label="Permalink to &quot;`a459f1d9af42` · [[PATCH net 10/15] netfilter: bridge: use DEBUG_NET_WARN_ON_ONCE in nf_ct_bridge_refrag()](https://lore.kernel.org/all/20261102005654.532438-11-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>将 nf_ct_bridge_refrag() 中的 WARN_ON 改为 DEBUG_NET_WARN_ON_ONCE。在 vlan filtering 桥上，若帧 tag 的协议与桥的 vlan_protocol 不同，br_allowed_ingress() 会把 tag 放回包中，导致 skb-&gt;protocol 既非 IPv4 也非 IPv6 而触发警告；在 panic_on_warn 配置下任何能发送分片的人都能打崩机器。</p><blockquote><p><strong>学习价值</strong>：说明 WARN_ON 在 panic_on_warn 场景下的 DoS 风险，以及 DEBUG_NET_WARN_ON_ONCE 的使用时机。</p></blockquote><h3 id="_16abd25a137e-·-patch-net-09-15-netfilter-nft-set-rbtree-check-catchall-sync-return-before-queue-done" tabindex="-1"><code>16abd25a137e</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-10-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 09/15] netfilter: nft_set_rbtree: check catchall_sync return before queue_done</a> <a class="header-anchor" href="#_16abd25a137e-·-patch-net-09-15-netfilter-nft-set-rbtree-check-catchall-sync-return-before-queue-done" aria-label="Permalink to &quot;`16abd25a137e` · [[PATCH net 09/15] netfilter: nft_set_rbtree: check catchall_sync return before queue_done](https://lore.kernel.org/all/20261102005654.532438-10-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 nft_set_rbtree 中 nft_rbtree_gc_queue() 将 nft_trans_gc_catchall_sync() 的返回值直接传给 nft_trans_gc_queue_sync_done() 的问题：当 catchall 路径刷满 GC batch 且 nft_trans_gc_alloc() 失败时返回 NULL，导致 NULL 指针解引用。修复是像 pipapo GC 路径一样增加 NULL 检查。</p><blockquote><p><strong>学习价值</strong>：展示了 nftables set GC 机制的错误处理细节，以及对照其他代码路径补齐防御性检查的常见修复模式。</p></blockquote><h3 id="_552ee160f8c3-·-patch-net-08-15-netfilter-flowtable-extend-ct-timeout-of-offloaded-gre-flows" tabindex="-1"><code>552ee160f8c3</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-9-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 08/15] netfilter: flowtable: extend ct timeout of offloaded GRE flows</a> <a class="header-anchor" href="#_552ee160f8c3-·-patch-net-08-15-netfilter-flowtable-extend-ct-timeout-of-offloaded-gre-flows" aria-label="Permalink to &quot;`552ee160f8c3` · [[PATCH net 08/15] netfilter: flowtable: extend ct timeout of offloaded GRE flows](https://lore.kernel.org/all/20261102005654.532438-9-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 flowtable 中 offloaded GRE 流的 conntrack 超时问题：nf_flow_table_extend_ct_timeout() 原本只处理 TCP 和 UDP，对其他四层协议触发 WARN_ON_ONCE。但 GRE 流自 commit 4e8d9584d154 起也可通过 nft_flow_offload 和 act_ct offload，导致其超时降至 5 分钟以下时触发警告。修复是增加对 GRE 的超时延长支持。</p><blockquote><p><strong>学习价值</strong>：帮助理解 flowtable offload 与 conntrack timeout 扩展的协作机制，以及新特性引入后旧假设失效的典型 bug。</p></blockquote><h3 id="_2bdcaade8746-·-patch-net-07-15-netfilter-nf-dup-preserve-guard-across-nfqueue-reinjection" tabindex="-1"><code>2bdcaade8746</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-8-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 07/15] netfilter: nf_dup: preserve guard across NFQUEUE reinjection</a> <a class="header-anchor" href="#_2bdcaade8746-·-patch-net-07-15-netfilter-nf-dup-preserve-guard-across-nfqueue-reinjection" aria-label="Permalink to &quot;`2bdcaade8746` · [[PATCH net 07/15] netfilter: nf_dup: preserve guard across NFQUEUE reinjection](https://lore.kernel.org/all/20261102005654.532438-8-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>修复 nf_dup 中 NFQUEUE 重注入破坏重复包防护的问题：NFQUEUE 可在 task-local duplication guard 已设置时挂起被复制包的遍历，输出调用返回后 guard 被清除，而后续 verdict 恢复遍历时 guard 已丢失。修复是将 guard 保存到 queue entry 中并在重注入继续 hook 遍历时恢复，同时处理嵌套同步重注入。</p><blockquote><p><strong>学习价值</strong>：深入展示了 netfilter hook 遍历、NFQUEUE 异步 verdict 与 per-task 状态的复杂交互，适合研究 netfilter 核心机制。</p></blockquote><h3 id="_5933a76ddb7c-·-patch-net-06-15-netfilter-nf-conntrack-limit-expectation-master-chain-depth" tabindex="-1"><code>5933a76ddb7c</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-7-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 06/15] netfilter: nf_conntrack: limit expectation master chain depth</a> <a class="header-anchor" href="#_5933a76ddb7c-·-patch-net-06-15-netfilter-nf-conntrack-limit-expectation-master-chain-depth" aria-label="Permalink to &quot;`5933a76ddb7c` · [[PATCH net 06/15] netfilter: nf_conntrack: limit expectation master chain depth](https://lore.kernel.org/all/20261102005654.532438-7-pablo@netfilter.org/)&quot;">​</a></h3><p><em>Pablo Neira Ayuso (<a href="mailto:pablo@netfilter.org" target="_blank" rel="noreferrer">pablo@netfilter.org</a>)｜netdev</em></p><p>限制 conntrack expectation 的 master 链深度：conntrack 可指向 master conntrack，而 master 又可指向更上层的 master，此前链深度无上限。修复是在 nf_ct_expect_alloc() 中遍历 master 链并拒绝超过 2 层嵌套的分配，同时新增 ctnetlink_find_get_master() 使 ctnetlink 创建路径返回 -EMLINK 而非误导性的 -ENOMEM。</p><blockquote><p><strong>学习价值</strong>：展示了无界数据结构导致的资源风险及防御性上限设计，也演示了如何改进错误码语义。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_3b2f27572219-·-linus-master-io-uring-sqpoll-22d9db9fd6-warning-at-io-uring-sqpoll-c-io-sq-thread-stop" tabindex="-1"><code>3b2f27572219</code> · <a href="https://lore.kernel.org/all/202611020832.6be281-lkp@intel.com/" target="_blank" rel="noreferrer">[linus:master] [io_uring/sqpoll] 22d9db9fd6: WARNING:at_io_uring/sqpoll.c:#io_sq_thread_stop</a> <a class="header-anchor" href="#_3b2f27572219-·-linus-master-io-uring-sqpoll-22d9db9fd6-warning-at-io-uring-sqpoll-c-io-sq-thread-stop" aria-label="Permalink to &quot;`3b2f27572219` · [[linus:master] [io_uring/sqpoll] 22d9db9fd6: WARNING:at_io_uring/sqpoll.c:#io_sq_thread_stop](https://lore.kernel.org/all/202611020832.6be281-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:yi1.lai@intel.com" target="_blank" rel="noreferrer">yi1.lai@intel.com</a>)｜lkml</em></p><p>kernel test robot 在 trinity 压力测试中报告 commit 22d9db9fd64a（&quot;io_uring/sqpoll: don&#39;t attach to a thread that is canceling&quot;）触发 io_sq_thread_stop 处的 WARNING。该问题出现在 sqpoll 线程取消与 attach 的竞态处理路径上，需要开发者确认修复。</p><blockquote><p><strong>学习价值</strong>：展示了 io_uring sqpoll 线程生命周期管理的竞态复杂性，是学习内核并发与测试机器人工作流的好案例。</p></blockquote><h3 id="d41ba9eabe6a-·-linus-master-ovl-a518e63c37-kselftests-filesystems-fscontext-ns-fscontext-ns-test-fscontext-ns-overlay-create-from-descendant-userns-fail" tabindex="-1"><code>d41ba9eabe6a</code> · <a href="https://lore.kernel.org/all/202611020115.2281e158-lkp@intel.com/" target="_blank" rel="noreferrer">[linus:master] [ovl] a518e63c37: kselftests.filesystems/fscontext_ns.fscontext_ns_test.fscontext_ns.overlay.create_from_descendant_userns.fail</a> <a class="header-anchor" href="#d41ba9eabe6a-·-linus-master-ovl-a518e63c37-kselftests-filesystems-fscontext-ns-fscontext-ns-test-fscontext-ns-overlay-create-from-descendant-userns-fail" aria-label="Permalink to &quot;`d41ba9eabe6a` · [[linus:master] [ovl] a518e63c37: kselftests.filesystems/fscontext_ns.fscontext_ns_test.fscontext_ns.overlay.create_from_descendant_userns.fail](https://lore.kernel.org/all/202611020115.2281e158-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:yi1.lai@intel.com" target="_blank" rel="noreferrer">yi1.lai@intel.com</a>)｜lkml</em></p><p>kernel test robot 报告 commit a518e63c3775（&quot;ovl: return EINVAL instead of EIO in case of mismatched user_ns&quot;）导致 fscontext_ns kselftest 中 overlay 的 create_from_descendant_userns 用例失败。错误码从 EIO 改为 EINVAL 后测试断言未同步更新，需确认是测试问题还是语义回归。</p><blockquote><p><strong>学习价值</strong>：提醒学习者内核错误码语义变更必须与 kselftest 断言保持一致，是理解 user namespace 与 overlayfs 交互的实例。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_334598042b53-·-cuda-oxide-0-3-vastly-improves-rust-support-for-nvidia-cuda-programming" tabindex="-1"><code>334598042b53</code> · <a href="https://www.phoronix.com/news/CUDA-Oxide-0.3" target="_blank" rel="noreferrer">CUDA Oxide 0.3 Vastly Improves Rust Support For NVIDIA CUDA Programming</a> <a class="header-anchor" href="#_334598042b53-·-cuda-oxide-0-3-vastly-improves-rust-support-for-nvidia-cuda-programming" aria-label="Permalink to &quot;`334598042b53` · [CUDA Oxide 0.3 Vastly Improves Rust Support For NVIDIA CUDA Programming](https://www.phoronix.com/news/CUDA-Oxide-0.3)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>NVIDIA 发布 CUDA Oxide 0.3，这是其实验性的 Rust 到 CUDA 编译器，近期开发非常活跃，大幅改进了对 Rust 语言编写 CUDA 代码的支持。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 在 GPU 计算生态中的扩展，对关注 Rust 语言生态（而非 Linux 内核 Rust）的学习者有一定参考价值。</p></blockquote><h3 id="_605114a8628b-·-patch-rfc-v2-4-4-bpf-mark-bpf-iter-sockmap-sk-as-ptr-trusted" tabindex="-1"><code>605114a8628b</code> · <a href="https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-4-e96a63c43b39@rbox.co/" target="_blank" rel="noreferrer">[PATCH RFC v2 4/4] bpf: Mark bpf_iter__sockmap::sk as PTR_TRUSTED</a> <a class="header-anchor" href="#_605114a8628b-·-patch-rfc-v2-4-4-bpf-mark-bpf-iter-sockmap-sk-as-ptr-trusted" aria-label="Permalink to &quot;`605114a8628b` · [[PATCH RFC v2 4/4] bpf: Mark bpf_iter__sockmap::sk as PTR_TRUSTED](https://lore.kernel.org/all/20261102-sockmap-update-limit-iter-v2-4-e96a63c43b39@rbox.co/)&quot;">​</a></h3><p><em>Michal Luczaj (<a href="mailto:mhal@rbox.co" target="_blank" rel="noreferrer">mhal@rbox.co</a>)｜lkml</em></p><p>该补丁将 bpf_iter__sockmap 中的 sk 字段标记为 PTR_TRUSTED，作为移除 plain PTR_TO_BTF_ID 工作的前置准备。标记后 BPF 程序可将该指针直接传给需要 trusted 参数的 bpf helper，仅修改 net/core/sock_map.c 中一处类型定义。</p><blockquote><p><strong>学习价值</strong>：有助于理解 BPF verifier 的指针类型系统（PTR_TRUSTED 与 PTR_TO_BTF_ID）及其演进方向。</p></blockquote><h3 id="_052e2743dce2-·-patch-v2-rust-serdev-use-delta-for-timeouts" tabindex="-1"><code>052e2743dce2</code> · <a href="https://lore.kernel.org/all/20261102005125.626125-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v2] rust: serdev: use Delta for timeouts</a> <a class="header-anchor" href="#_052e2743dce2-·-patch-v2-rust-serdev-use-delta-for-timeouts" aria-label="Permalink to &quot;`052e2743dce2` · [[PATCH v2] rust: serdev: use Delta for timeouts](https://lore.kernel.org/all/20261102005125.626125-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>修改 rust serdev 抽象中 write_all() 和 wait_until_sent() 的超时参数类型，从裸的 c_ulong（Jiffies）改为 Delta&lt;Jiffy&gt;，使单位在类型层面可见。C 侧将超时 0 解释为无限等待，Rust API 不保留该语义，而是要求调用者显式传入 Delta::from_jiffies(isize::MAX)（即 MAX_SCHEDULE_TIMEOUT）来表达无限等待。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust for Linux 中如何用类型系统（Delta&lt;Jiffy&gt;）消除单位歧义，并处理 C API 中魔法值语义的映射问题，是 API 设计的好案例。</p></blockquote><h3 id="a1bed9907992-·-patch-v1-rust-hrtimer-remove-hrtimer-expires" tabindex="-1"><code>a1bed9907992</code> · <a href="https://lore.kernel.org/all/20261102000102.603124-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1] rust: hrtimer: Remove HrTimer::expires()</a> <a class="header-anchor" href="#a1bed9907992-·-patch-v1-rust-hrtimer-remove-hrtimer-expires" aria-label="Permalink to &quot;`a1bed9907992` · [[PATCH v1] rust: hrtimer: Remove HrTimer::expires()](https://lore.kernel.org/all/20261102000102.603124-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>移除 HrTimer::expires()，因为它在不持有 base lock 的情况下读取 node.expires，而 hrtimer_start() 和 hrtimer_forward() 会并发写入该字段，构成 Rust 中未定义行为的数据竞争。即使加锁读取，得到的也只是快照，另一 CPU 可能在读取后立即重新启动定时器改变到期时间，因此该接口无法安全提供。</p><blockquote><p><strong>学习价值</strong>：生动说明了 safe Rust 抽象为何必须删除无法证明无竞争的接口，对理解 Rust 内存安全模型与内核并发交互很有启发。</p></blockquote><h3 id="_75f9e1c60b41-·-patch-v1-2-2-rust-hrtimer-use-hrtimer-forward-safe-from-callback" tabindex="-1"><code>75f9e1c60b41</code> · <a href="https://lore.kernel.org/all/20261101232829.593680-3-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1 2/2] rust: hrtimer: Use hrtimer_forward_safe_from_callback()</a> <a class="header-anchor" href="#_75f9e1c60b41-·-patch-v1-2-2-rust-hrtimer-use-hrtimer-forward-safe-from-callback" aria-label="Permalink to &quot;`75f9e1c60b41` · [[PATCH v1 2/2] rust: hrtimer: Use hrtimer_forward_safe_from_callback()](https://lore.kernel.org/all/20261101232829.593680-3-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>Rust 的 safe 代码可以在定时器回调运行期间通过 Arc&lt;T&gt; 或 Pin&lt;&amp;T&gt; 的其他克隆再次启动定时器，而 HrTimerCallbackContext::forward() 调用的 hrtimer_forward() 在无 base lock 时写 expiry，可能与并发的 hrtimer_start() 竞争。补丁改为调用 hrtimer_forward_safe_from_callback()，它在持有 base lock 时完成检查和更新；若定时器已被并发启动排队，则保留 expiry 不动并返回 0。</p><blockquote><p><strong>学习价值</strong>：揭示了回调中 forward 与并发 start 的竞争细节，是学习 hrtimer 内部锁协议和 Rust safe API 约束的优质材料。</p></blockquote><h3 id="_950cbde21445-·-patch-v1-1-2-hrtimer-add-hrtimer-forward-safe-from-callback" tabindex="-1"><code>950cbde21445</code> · <a href="https://lore.kernel.org/all/20261101232829.593680-2-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1 1/2] hrtimer: Add hrtimer_forward_safe_from_callback()</a> <a class="header-anchor" href="#_950cbde21445-·-patch-v1-1-2-hrtimer-add-hrtimer-forward-safe-from-callback" aria-label="Permalink to &quot;`950cbde21445` · [[PATCH v1 1/2] hrtimer: Add hrtimer_forward_safe_from_callback()](https://lore.kernel.org/all/20261101232829.593680-2-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>为 hrtimer 核心新增 hrtimer_forward_safe_from_callback() 变体：在持有 base lock 的情况下完成检查和 expiry 更新，避免 hrtimer_forward() 的无锁写入与并发 hrtimer_start() 竞争而破坏已排队定时器的排序键。若定时器已被排队，则保留 hrtimer_start() 设置的 expiry。首个用户是 Rust hrtimer 抽象，因为 safe Rust 允许在回调运行期间重新启动定时器。</p><blockquote><p><strong>学习价值</strong>：展示了在 C 核心中为支撑 Rust safe 抽象而新增基础设施的典型流程，可顺带学习 hrtimer 的排队与排序机制。</p></blockquote><h3 id="_8e91cf16d1c7-·-patch-v1-0-2-hrtimer-add-hrtimer-forward-safe-from-callback-1" tabindex="-1"><code>8e91cf16d1c7</code> · <a href="https://lore.kernel.org/all/20261101232829.593680-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1 0/2] hrtimer: Add hrtimer_forward_safe_from_callback()</a> <a class="header-anchor" href="#_8e91cf16d1c7-·-patch-v1-0-2-hrtimer-add-hrtimer-forward-safe-from-callback-1" aria-label="Permalink to &quot;`8e91cf16d1c7` · [[PATCH v1 0/2] hrtimer: Add hrtimer_forward_safe_from_callback()](https://lore.kernel.org/all/20261101232829.593680-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>补丁系列封面：由于 safe Rust 代码可在回调运行期间重新启动定时器，Rust 抽象无法将 hrtimer_forward() 作为安全 API 提供给回调使用。按 Thomas Gleixner 的建议新增一个在 base lock 下完成检查与更新的辅助函数（patch 1），并让 Rust 回调上下文改用它（patch 2）。该辅助函数并非 Rust 专用，i915_pmu 和 null_blk 也可受益。</p><blockquote><p><strong>学习价值</strong>：说明 Rust 抽象的需求如何反哺 C 核心代码改进，体现了两个语言生态协作演进的典型路径。</p></blockquote><h3 id="a9b7df19b757-·-patch-v2-1-2-rust-str-parse-int-only-accept-a-sign-before-the-radix-prefix" tabindex="-1"><code>a9b7df19b757</code> · <a href="https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-1-0fd827f52070@younes.io/" target="_blank" rel="noreferrer">[PATCH v2 1/2] rust: str: parse_int: only accept a sign before the radix prefix</a> <a class="header-anchor" href="#a9b7df19b757-·-patch-v2-1-2-rust-str-parse-int-only-accept-a-sign-before-the-radix-prefix" aria-label="Permalink to &quot;`a9b7df19b757` · [[PATCH v2 1/2] rust: str: parse_int: only accept a sign before the radix prefix](https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-1-0fd827f52070@younes.io/)&quot;">​</a></h3><p><em>Younes Akhouayri via B4 Relay (<a href="mailto:devnull+git.younes.io@kernel.org" target="_blank" rel="noreferrer">devnull+git.younes.io@kernel.org</a>)｜rust-for-linux</em></p><p>修复 rust str 模块中 ParseInt::from_str() 的符号处理：原实现剥离可选的 &#39;-&#39; 和进制前缀后交给 core 的 from_str_radix()，导致前缀后出现符号或双重符号的输入（如 &quot;0x-5&quot;、&quot;-+5&quot;）被错误接受，而 kstrtol() 对这些均返回 -EINVAL。补丁限制符号只能出现在进制前缀之前，与 C 侧行为对齐。</p><blockquote><p><strong>学习价值</strong>：通过对比 Rust core 库与内核 kstrtol() 的解析语义差异，展示了跨语言 API 行为一致性对内核 Rust 抽象的重要性。</p></blockquote><h3 id="d0e9c19abc84-·-patch-v2-2-2-rust-str-parse-int-accept-a-trailing-newline-like-kstrtol" tabindex="-1"><code>d0e9c19abc84</code> · <a href="https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-2-0fd827f52070@younes.io/" target="_blank" rel="noreferrer">[PATCH v2 2/2] rust: str: parse_int: accept a trailing newline like kstrtol()</a> <a class="header-anchor" href="#d0e9c19abc84-·-patch-v2-2-2-rust-str-parse-int-accept-a-trailing-newline-like-kstrtol" aria-label="Permalink to &quot;`d0e9c19abc84` · [[PATCH v2 2/2] rust: str: parse_int: accept a trailing newline like kstrtol()](https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-2-0fd827f52070@younes.io/)&quot;">​</a></h3><p><em>Younes Akhouayri via B4 Relay (<a href="mailto:devnull+git.younes.io@kernel.org" target="_blank" rel="noreferrer">devnull+git.younes.io@kernel.org</a>)｜rust-for-linux</em></p><p>ParseInt 的文档声称 kstrtol()/kstrtoul() 能解析的字符串 from_str() 也能解析，但前者接受单个尾部换行符而后者不接受。由于用户空间写入（如 echo 到 sysfs 文件）常带尾部换行，补丁在解析前剥离单个尾部换行符并添加 doctest，修复了文档承诺与实现的偏差。</p><blockquote><p><strong>学习价值</strong>：提醒学习者 sysfs 输入常带换行符这一实际场景，并展示了以文档契约为准修复 API 行为的规范做法。</p></blockquote><h3 id="_0898e3209224-·-patch-v2-0-2-rust-str-parse-int-match-kstrtol-sign-and-newline-handling" tabindex="-1"><code>0898e3209224</code> · <a href="https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-0-0fd827f52070@younes.io/" target="_blank" rel="noreferrer">[PATCH v2 0/2] rust: str: parse_int: match kstrtol() sign and newline handling</a> <a class="header-anchor" href="#_0898e3209224-·-patch-v2-0-2-rust-str-parse-int-match-kstrtol-sign-and-newline-handling" aria-label="Permalink to &quot;`0898e3209224` · [[PATCH v2 0/2] rust: str: parse_int: match kstrtol() sign and newline handling](https://lore.kernel.org/all/20261101-b4-parse-int-sign-v2-0-0fd827f52070@younes.io/)&quot;">​</a></h3><p><em>Younes Akhouayri via B4 Relay (<a href="mailto:devnull+git.younes.io@kernel.org" target="_blank" rel="noreferrer">devnull+git.younes.io@kernel.org</a>)｜rust-for-linux</em></p><p>系列封面：ParseInt 文档承诺与 kstrtol()/kstrtoul() 行为一致，但实际存在双向偏差——from_str() 接受 &quot;0x-5&quot;、&quot;0x+5&quot;、&quot;-+5&quot; 等 kstrtol() 拒绝的输入，却拒绝 kstrtol() 接受的 &quot;+0x5&quot; 和 &quot;5\\n&quot;。Patch 1 限制符号只能位于进制前缀之前，patch 2 接受单个尾部换行符；0o 和 0b 前缀作为 Rust 扩展保持不变。</p><blockquote><p><strong>学习价值</strong>：以清晰的对照表展示 API 语义对齐问题，是理解内核 Rust 抽象需严格匹配 C 行为的典型案例。</p></blockquote><h3 id="_9f0afcbb56c4-·-patch-rust-bindings-derive-zeroable-for-bindgen-s-opaque-array-wrappers" tabindex="-1"><code>9f0afcbb56c4</code> · <a href="https://lore.kernel.org/all/20261031152846.746656-1-sashal@kernel.org/" target="_blank" rel="noreferrer">[PATCH] rust: bindings: derive Zeroable for bindgen&#39;s opaque array wrappers</a> <a class="header-anchor" href="#_9f0afcbb56c4-·-patch-rust-bindings-derive-zeroable-for-bindgen-s-opaque-array-wrappers" aria-label="Permalink to &quot;`9f0afcbb56c4` · [[PATCH] rust: bindings: derive Zeroable for bindgen&#39;s opaque array wrappers](https://lore.kernel.org/all/20261031152846.746656-1-sashal@kernel.org/)&quot;">​</a></h3><p><em>Sasha Levin (<a href="mailto:sashal@kernel.org" target="_blank" rel="noreferrer">sashal@kernel.org</a>)｜rust-for-linux</em></p><p>bindgen 0.73 将部分 opaque 类型（如对齐超过 4 字节的）生成为 __BindgenOpaqueArray 新类型而非普通数组，该新类型未实现 Zeroable，导致嵌入此类 opaque 类型的结构体不再满足 Zeroable。例如开启 lockdep 时 spinlock 变为 __BindgenOpaqueArray8&lt;[u8; 72]&gt;，影响相关代码。补丁为这些包装类型派生 Zeroable 以恢复原行为。</p><blockquote><p><strong>学习价值</strong>：展示了 bindgen 版本升级如何意外破坏 Rust 抽象的 trait 派生链，是理解 Rust 内核构建系统脆弱性的实用案例。</p></blockquote><h3 id="_64c52b0ca6b4-·-patch-v2-rust-binder-use-atomic-add-in-binderstats" tabindex="-1"><code>64c52b0ca6b4</code> · <a href="https://lore.kernel.org/all/20261031150909.3807811-1-jenhaochen@google.com/" target="_blank" rel="noreferrer">[PATCH v2] rust_binder: use Atomic::add() in BinderStats</a> <a class="header-anchor" href="#_64c52b0ca6b4-·-patch-v2-rust-binder-use-atomic-add-in-binderstats" aria-label="Permalink to &quot;`64c52b0ca6b4` · [[PATCH v2] rust_binder: use Atomic::add() in BinderStats](https://lore.kernel.org/all/20261031150909.3807811-1-jenhaochen@google.com/)&quot;">​</a></h3><p><em>Jenhao Chen (<a href="mailto:jenhaochen@google.com" target="_blank" rel="noreferrer">jenhaochen@google.com</a>)｜rust-for-linux</em></p><p>rust_binder 的 BinderStats::inc_bc()/inc_br() 用 Atomic::fetch_add(1, Relaxed) 递增计数器但丢弃返回值，编译器被迫生成带返回值的原子指令（arm64 LSE 的 LDADD、x86 的 LOCK XADD），而非更廉价的无返回值版本（STADD、LOCK ADD）。补丁改用 Atomic::add()，在 arm64 LSE 上可生成更精简的指令。</p><blockquote><p><strong>学习价值</strong>：细致讲解了 Rust 原子操作 API 选择如何直接影响底层指令生成，对性能敏感的内核 Rust 代码编写很有参考价值。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_2733cd01500f-·-linux-7-4-rc1-released-with-nice-performance-improvements-amd-ryzen-zen-6-preparations-amdgpu-hdmi-2-1-default" tabindex="-1"><code>2733cd01500f</code> · <a href="https://www.phoronix.com/news/Linux-7.4-rc1" target="_blank" rel="noreferrer">Linux 7.4-rc1 Released With Nice Performance Improvements, AMD Ryzen Zen 6 Preparations &amp; AMDGPU HDMI 2.1 Default</a> <a class="header-anchor" href="#_2733cd01500f-·-linux-7-4-rc1-released-with-nice-performance-improvements-amd-ryzen-zen-6-preparations-amdgpu-hdmi-2-1-default" aria-label="Permalink to &quot;`2733cd01500f` · [Linux 7.4-rc1 Released With Nice Performance Improvements, AMD Ryzen Zen 6 Preparations &amp; AMDGPU HDMI 2.1 Default](https://www.phoronix.com/news/Linux-7.4-rc1)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linus Torvalds 按期发布了 Linux 7.4-rc1，结束了 7.4 的 merge window。本次更新包含多项性能改进、AMD Ryzen Zen 6 的前期准备代码，以及 AMDGPU 驱动默认启用 HDMI 2.1 支持。</p><blockquote><p><strong>学习价值</strong>：跟踪每个内核版本的 rc1 发布是了解当前 merge window 合入了哪些子系统变化的好切入点。</p></blockquote><h3 id="_43f7b97beb5f-·-kwi-being-developed-as-new-kde-terminal-emulator-with-3x-to-35x-performance" tabindex="-1"><code>43f7b97beb5f</code> · <a href="https://www.phoronix.com/news/KDE-Kwi-Terminal-Emulator" target="_blank" rel="noreferrer">Kwi Being Developed As New KDE Terminal Emulator With 3x To 35x Performance</a> <a class="header-anchor" href="#_43f7b97beb5f-·-kwi-being-developed-as-new-kde-terminal-emulator-with-3x-to-35x-performance" aria-label="Permalink to &quot;`43f7b97beb5f` · [Kwi Being Developed As New KDE Terminal Emulator With 3x To 35x Performance](https://www.phoronix.com/news/KDE-Kwi-Terminal-Emulator)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE 社区正在开发新的终端模拟器 Kwi，作为 Konsole 的现代化替代方案，基于 Ghostty 库构建，宣称性能提升 3 到 35 倍。这是用户态应用新闻，与内核本身无直接关系。</p><blockquote><p><strong>学习价值</strong>：与内核学习无关，可忽略；仅作为开源生态动态了解。</p></blockquote><h3 id="_919159281761-·-linux-s-perf-python-scripts-more-robust-faster-with-linux-7-4" tabindex="-1"><code>919159281761</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Perf-Tools" target="_blank" rel="noreferrer">Linux&#39;s Perf Python Scripts More Robust &amp; Faster With Linux 7.4</a> <a class="header-anchor" href="#_919159281761-·-linux-s-perf-python-scripts-more-robust-faster-with-linux-7-4" aria-label="Permalink to &quot;`919159281761` · [Linux&#39;s Perf Python Scripts More Robust &amp; Faster With Linux 7.4](https://www.phoronix.com/news/Linux-7.4-Perf-Tools)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 合入了 perf 子系统工具链的更新，其中最显著的是对 Python 代码的大幅重构（overhaul），使 perf 的 Python 脚本更加健壮且运行更快。perf 是 Linux 上处理性能计数器等分析任务的核心工具。</p><blockquote><p><strong>学习价值</strong>：perf 是内核学习者必学的性能分析工具，了解其脚本基础设施的改进有助于编写更可靠的自定义分析脚本。</p></blockquote><h3 id="f53bf007d926-·-kde-plasma-6-9-lands-some-new-performance-optimizations" tabindex="-1"><code>f53bf007d926</code> · <a href="https://www.phoronix.com/news/KDE-Plasma-6.9-More-Performance" target="_blank" rel="noreferrer">KDE Plasma 6.9 Lands Some New Performance Optimizations</a> <a class="header-anchor" href="#f53bf007d926-·-kde-plasma-6-9-lands-some-new-performance-optimizations" aria-label="Permalink to &quot;`f53bf007d926` · [KDE Plasma 6.9 Lands Some New Performance Optimizations](https://www.phoronix.com/news/KDE-Plasma-6.9-More-Performance)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>KDE Plasma 6.9 开发正在加速，本周合入了多项性能优化。这些改进属于用户空间桌面环境层面，与内核性能调优无直接关联。</p><blockquote><p><strong>学习价值</strong>：对内核学习价值较低，仅可作为桌面 Linux 生态的背景了解。</p></blockquote><h3 id="_7138da1a8595-·-wine-11-21-released-with-better-wow64-opengl-performance" tabindex="-1"><code>7138da1a8595</code> · <a href="https://www.phoronix.com/news/Wine-11.21-Released" target="_blank" rel="noreferrer">Wine 11.21 Released With Better WoW64 OpenGL Performance</a> <a class="header-anchor" href="#_7138da1a8595-·-wine-11-21-released-with-better-wow64-opengl-performance" aria-label="Permalink to &quot;`7138da1a8595` · [Wine 11.21 Released With Better WoW64 OpenGL Performance](https://www.phoronix.com/news/Wine-11.21-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Wine 11.21 发布，改进了 WoW64 模式下的 OpenGL 性能。Wine 12.0 稳定版预计将在明年初发布，相关准备工作即将启动。</p><blockquote><p><strong>学习价值</strong>：属于用户空间 Windows 兼容层项目，与内核学习关联不大。</p></blockquote><h3 id="_397d4aabaf99-·-drivers-hwtracing-stm-core-c-509-8-24-warning-stm-fops-write-has-stream-semantic-safe-to-change-nonseekable-open-stream-open-fwd" tabindex="-1"><code>397d4aabaf99</code> · <a href="https://lore.kernel.org/all/f887f7b3-b72c-99d2-8dbf-96cbd83774bf@inria.fr/" target="_blank" rel="noreferrer">drivers/hwtracing/stm/core.c:509:8-24: WARNING: stm_fops: .write() has stream semantic; safe to change nonseekable_open -&gt; stream_open. (fwd)</a> <a class="header-anchor" href="#_397d4aabaf99-·-drivers-hwtracing-stm-core-c-509-8-24-warning-stm-fops-write-has-stream-semantic-safe-to-change-nonseekable-open-stream-open-fwd" aria-label="Permalink to &quot;`397d4aabaf99` · [drivers/hwtracing/stm/core.c:509:8-24: WARNING: stm_fops: .write() has stream semantic; safe to change nonseekable_open -&gt; stream_open. (fwd)](https://lore.kernel.org/all/f887f7b3-b72c-99d2-8dbf-96cbd83774bf@inria.fr/)&quot;">​</a></h3><p><em>Julia Lawall (<a href="mailto:julia.lawall@inria.fr" target="_blank" rel="noreferrer">julia.lawall@inria.fr</a>)｜linux-mm</em></p><p>kernel test robot 报告 STM（System Trace Module）驱动的 stm_fops 中 .write() 实现具有流式语义，建议将 nonseekable_open 改为 stream_open 以避免 lseek 相关的潜在问题。Julia Lawall 仅转发该报告。</p><blockquote><p><strong>学习价值</strong>：展示了 stream_open 与 nonseekable_open 的区别，是理解内核文件操作语义细节的小知识点。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_6180adcfc0d7-·-7-3-1-stable" tabindex="-1"><code>6180adcfc0d7</code> · <a href="https://www.kernel.org/#kernel.org-stable-7.3.1-2026-10-30" target="_blank" rel="noreferrer">7.3.1: stable</a> <a class="header-anchor" href="#_6180adcfc0d7-·-7-3-1-stable" aria-label="Permalink to &quot;`6180adcfc0d7` · [7.3.1: stable](https://www.kernel.org/#kernel.org-stable-7.3.1-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 stable 版本 7.3.1，发布日期为 2026-10-30。提供 linux-7.3.1.tar.xz 源码包、PGP 签名、完整 patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：了解 stable 版本的发布流程与 PGP 签名校验，是内核学习者跟进主线更新的基础。</p></blockquote><h3 id="_34c75aa166e8-·-7-2-15-stable" tabindex="-1"><code>34c75aa166e8</code> · <a href="https://www.kernel.org/#kernel.org-stable-7.2.15-2026-11-01" target="_blank" rel="noreferrer">7.2.15: stable</a> <a class="header-anchor" href="#_34c75aa166e8-·-7-2-15-stable" aria-label="Permalink to &quot;`34c75aa166e8` · [7.2.15: stable](https://www.kernel.org/#kernel.org-stable-7.2.15-2026-11-01)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 7.2.15 版本，标记为 EOL（End of Life）的 stable 版本，发布日期为 2026-11-01。提供源码包、PGP 签名、完整及增量 patch 与 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：EOL 标记提醒学习者关注内核版本的生命周期管理，理解何时应迁移到更新的维护分支。</p></blockquote><h3 id="_2c4320b9c143-·-6-18-60-longterm" tabindex="-1"><code>2c4320b9c143</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.18.60-2026-10-30" target="_blank" rel="noreferrer">6.18.60: longterm</a> <a class="header-anchor" href="#_2c4320b9c143-·-6-18-60-longterm" aria-label="Permalink to &quot;`2c4320b9c143` · [6.18.60: longterm](https://www.kernel.org/#kernel.org-longterm-6.18.60-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 6.18.60，发布日期为 2026-10-30。提供源码 tarball、PGP 签名、完整与增量 patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：longterm 内核是生产环境部署的重点，学习者应理解 longterm 与 stable 版本的维护策略差异。</p></blockquote><h3 id="_28b087fd52fe-·-6-12-115-longterm" tabindex="-1"><code>28b087fd52fe</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.12.115-2026-10-30" target="_blank" rel="noreferrer">6.12.115: longterm</a> <a class="header-anchor" href="#_28b087fd52fe-·-6-12-115-longterm" aria-label="Permalink to &quot;`28b087fd52fe` · [6.12.115: longterm](https://www.kernel.org/#kernel.org-longterm-6.12.115-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 6.12.115，发布日期为 2026-10-30。提供 linux-6.12.115.tar.xz 源码、PGP 签名、完整与增量 patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：跟踪 longterm 分支的补丁更新有助于学习者理解 backport 机制与稳定分支维护实践。</p></blockquote><h3 id="_717d0cf1e659-·-6-6-161-longterm" tabindex="-1"><code>717d0cf1e659</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.6.161-2026-10-30" target="_blank" rel="noreferrer">6.6.161: longterm</a> <a class="header-anchor" href="#_717d0cf1e659-·-6-6-161-longterm" aria-label="Permalink to &quot;`717d0cf1e659` · [6.6.161: longterm](https://www.kernel.org/#kernel.org-longterm-6.6.161-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 6.6.161，发布日期为 2026-10-30。提供源码包、PGP 签名、完整与增量 patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：多版本 longterm 并行维护展示了内核社区的长期支持体系，适合了解版本管理全景。</p></blockquote><h3 id="_881c4301384e-·-6-1-191-longterm" tabindex="-1"><code>881c4301384e</code> · <a href="https://www.kernel.org/#kernel.org-longterm-6.1.191-2026-10-30" target="_blank" rel="noreferrer">6.1.191: longterm</a> <a class="header-anchor" href="#_881c4301384e-·-6-1-191-longterm" aria-label="Permalink to &quot;`881c4301384e` · [6.1.191: longterm](https://www.kernel.org/#kernel.org-longterm-6.1.191-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 6.1.191，发布日期为 2026-10-30。提供 linux-6.1.191.tar.xz 源码、PGP 签名、patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：6.1 系列 longterm 的持续更新体现了老版本内核的长期安全维护，对嵌入式学习者尤具参考价值。</p></blockquote><h3 id="d6156e4655f4-·-5-15-224-longterm" tabindex="-1"><code>d6156e4655f4</code> · <a href="https://www.kernel.org/#kernel.org-longterm-5.15.224-2026-10-30" target="_blank" rel="noreferrer">5.15.224: longterm</a> <a class="header-anchor" href="#d6156e4655f4-·-5-15-224-longterm" aria-label="Permalink to &quot;`d6156e4655f4` · [5.15.224: longterm](https://www.kernel.org/#kernel.org-longterm-5.15.224-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 5.15.224，发布日期为 2026-10-30。提供源码包、PGP 签名、完整与增量 patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：5.15 作为广泛部署的 longterm 内核，其更新日志是学习 bugfix 回溯实践的好素材。</p></blockquote><h3 id="c0abcb212f0b-·-5-10-273-longterm" tabindex="-1"><code>c0abcb212f0b</code> · <a href="https://www.kernel.org/#kernel.org-longterm-5.10.273-2026-10-30" target="_blank" rel="noreferrer">5.10.273: longterm</a> <a class="header-anchor" href="#c0abcb212f0b-·-5-10-273-longterm" aria-label="Permalink to &quot;`c0abcb212f0b` · [5.10.273: longterm](https://www.kernel.org/#kernel.org-longterm-5.10.273-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>kernel.org 发布 longterm 版本 5.10.273，发布日期为 2026-10-30。提供 linux-5.10.273.tar.xz 源码、PGP 签名、patch 及 ChangeLog。</p><blockquote><p><strong>学习价值</strong>：5.10 系列的超长维护周期展示了企业级 LTS 内核的演进方式，适合研究旧内核的持续修复策略。</p></blockquote><h3 id="ab5e980142b8-·-next-20261030-linux-next" tabindex="-1"><code>ab5e980142b8</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261030-2026-10-30" target="_blank" rel="noreferrer">next-20261030: linux-next</a> <a class="header-anchor" href="#ab5e980142b8-·-next-20261030-linux-next" aria-label="Permalink to &quot;`ab5e980142b8` · [next-20261030: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261030-2026-10-30)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 发布 next-20261030 快照，日期为 2026-10-30。linux-next 是进入主线前各子系统分支代码的集成测试树。</p><blockquote><p><strong>学习价值</strong>：关注 linux-next 是提前观察即将合入主线的新特性与潜在冲突的重要途径，对参与内核开发的学习者很有价值。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_6c265b33e7cf-·-kernel-prepatch-7-4-rc1" tabindex="-1"><code>6c265b33e7cf</code> · <a href="https://lwn.net/Articles/1104654/" target="_blank" rel="noreferrer">Kernel prepatch 7.4-rc1</a> <a class="header-anchor" href="#_6c265b33e7cf-·-kernel-prepatch-7-4-rc1" aria-label="Permalink to &quot;`6c265b33e7cf` · [Kernel prepatch 7.4-rc1](https://lwn.net/Articles/1104654/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Linus Torvalds 发布了 7.4-rc1 内核预补丁，标志着本开发周期的 merge window 关闭。他称这是一个特别大的 merge window，并认为其中大量由 AI 触发的工作直接进入 merge window 而非以 -rc 阶段修复的形式出现，是开发流程更健康的信号。</p><blockquote><p><strong>学习价值</strong>：帮助学习者理解内核发布节奏中 merge window 与 -rc 阶段的角色，以及 AI 辅助开发对上游流程的影响。</p></blockquote><h3 id="_17e26b522f8e-·-final-release-for-the-7-2-stable-series" tabindex="-1"><code>17e26b522f8e</code> · <a href="https://lwn.net/Articles/1104629/" target="_blank" rel="noreferrer">Final release for the 7.2 stable series</a> <a class="header-anchor" href="#_17e26b522f8e-·-final-release-for-the-7-2-stable-series" aria-label="Permalink to &quot;`17e26b522f8e` · [Final release for the 7.2 stable series](https://lwn.net/Articles/1104629/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Greg Kroah-Hartman 宣布发布 7.2.15 内核，这是 7.2.y 稳定系列的最后一个版本，之后该分支进入 end-of-life。他解释说提前结束生命周期是为了避免同时维护过多分支，建议用户迁移到 7.3.y。</p><blockquote><p><strong>学习价值</strong>：展示了 stable 内核分支维护的取舍逻辑，对理解内核稳定版生命周期管理有参考价值。</p></blockquote><h3 id="_02263ebcf448-·-a-massive-pile-of-security-updates-for-saturday" tabindex="-1"><code>02263ebcf448</code> · <a href="https://lwn.net/Articles/1104612/" target="_blank" rel="noreferrer">A massive pile of security updates for Saturday</a> <a class="header-anchor" href="#_02263ebcf448-·-a-massive-pile-of-security-updates-for-saturday" aria-label="Permalink to &quot;`02263ebcf448` · [A massive pile of security updates for Saturday](https://lwn.net/Articles/1104612/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>AlmaLinux、Debian 和 Fedora 等发行版发布了大量安全更新，涉及 curl、bind、chromium、containerd、tomcat 等众多软件包。这是 LWN 常规的发行版安全更新汇总。</p><blockquote><p><strong>学习价值</strong>：属于发行版层面的安全公告汇总，对内核本身学习价值有限，但可了解生态安全维护概况。</p></blockquote><h3 id="f07eec3ca7ed-·-how-we-could-have-backdoored-bash-hacktron-blog" tabindex="-1"><code>f07eec3ca7ed</code> · <a href="https://lwn.net/Articles/1104262/" target="_blank" rel="noreferrer">How We Could Have Backdoored Bash (Hacktron blog)</a> <a class="header-anchor" href="#f07eec3ca7ed-·-how-we-could-have-backdoored-bash-hacktron-blog" aria-label="Permalink to &quot;`f07eec3ca7ed` · [How We Could Have Backdoored Bash (Hacktron blog)](https://lwn.net/Articles/1104262/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Hacktron 博客披露该团队如何攻破 GNU Savannah 代码托管平台：利用一个特殊构造的邮箱地址实现后端远程代码执行，随后提权为超级用户并冒充 Bash 维护者，验证可以向上游 Bash 仓库推送恶意代码，还借助未打补丁的内核获得 root 权限。漏洞已于 2026 年 5 月报告给 FSF。</p><blockquote><p><strong>学习价值</strong>：是供应链攻击的真实案例研究，展示了从 forge 入侵到内核提权的完整链条，对理解开源供应链安全很有启发。</p></blockquote><h3 id="c261aaa452f3-·-removing-binder-c-1" tabindex="-1"><code>c261aaa452f3</code> · <a href="https://lwn.net/Articles/1102982/" target="_blank" rel="noreferrer">[$] Removing binder.c</a> <a class="header-anchor" href="#c261aaa452f3-·-removing-binder-c-1" aria-label="Permalink to &quot;`c261aaa452f3` · [[$] Removing binder.c](https://lwn.net/Articles/1102982/)&quot;">​</a></h3><p><em>daroc｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>在 Kangrejos 2026 大会上，Carlos Llamas 宣布删除了 Android Binder 驱动的 C 语言实现，Binder 是 Android 的核心进程间通信机制。Alice Ryhl 补充介绍了用 Rust 实现替换 C 实现过程中最困难和有趣的部分。</p><blockquote><p><strong>学习价值</strong>：是 Linux 内核中大型 C 驱动迁移到 Rust 的标志性案例，对关注 Rust in Linux 的学习者极具参考价值。</p></blockquote><h3 id="_4a66fbc3bfb7-·-haas-postgres-19-is-late-and-it-s-ai-s-fault" tabindex="-1"><code>4a66fbc3bfb7</code> · <a href="https://lwn.net/Articles/1104210/" target="_blank" rel="noreferrer">Haas: Postgres 19 is late, and it&#39;s AI&#39;s fault</a> <a class="header-anchor" href="#_4a66fbc3bfb7-·-haas-postgres-19-is-late-and-it-s-ai-s-fault" aria-label="Permalink to &quot;`4a66fbc3bfb7` · [Haas: Postgres 19 is late, and it&#39;s AI&#39;s fault](https://lwn.net/Articles/1104210/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>PostgreSQL 开发者 Robert Haas 撰文讨论 PostgreSQL 19 发布延迟的原因，指出 LLM 能发现人类四十年都没找到的 bug，导致修复工作量激增。他认为短期延迟不是问题，但长期来看项目如何跟上 AI 发现 bug 的速度并持续创新令人担忧。</p><blockquote><p><strong>学习价值</strong>：虽非内核内容，但对理解 AI 工具对大型开源项目维护模式的冲击有思考价值。</p></blockquote><h3 id="_2dad4c759ead-·-system-call-wrappers-for-glibc" tabindex="-1"><code>2dad4c759ead</code> · <a href="https://lwn.net/Articles/1101647/" target="_blank" rel="noreferrer">[$] System-call wrappers for glibc</a> <a class="header-anchor" href="#_2dad4c759ead-·-system-call-wrappers-for-glibc" aria-label="Permalink to &quot;`2dad4c759ead` · [[$] System-call wrappers for glibc](https://lwn.net/Articles/1101647/)&quot;">​</a></h3><p><em>jake｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>在 2026 年 Linux Plumbers Conference 上，glibc 维护者 Carlos O&#39;Donell 和 Florian Weimer 介绍了缺少 glibc 封装的 Linux 系统调用的进展，这些调用目前只能通过 syscall() 访问。他们还收集了与会者对系统调用封装的需求。</p><blockquote><p><strong>学习价值</strong>：有助于理解内核系统调用与用户态 C 库之间的接口层设计，以及 glibc 封装策略的演进。</p></blockquote><h3 id="be6e456edc08-·-eight-more-stable-kernel-updates" tabindex="-1"><code>be6e456edc08</code> · <a href="https://lwn.net/Articles/1104177/" target="_blank" rel="noreferrer">Eight more stable kernel updates</a> <a class="header-anchor" href="#be6e456edc08-·-eight-more-stable-kernel-updates" aria-label="Permalink to &quot;`be6e456edc08` · [Eight more stable kernel updates](https://lwn.net/Articles/1104177/)&quot;">​</a></h3><p><em>daroc｜lwn</em></p><p>Greg Kroah-Hartman 发布了 7.3.1、7.2.14、6.18.60、6.12.115、6.6.161、6.1.191、5.15.224 和 5.10.273 共八个稳定内核更新。他建议所有用户及时升级，尤其考虑到近期安全相关修复数量增加。</p><blockquote><p><strong>学习价值</strong>：常规 stable 内核发布通告，可用于跟踪各稳定分支的维护状态。</p></blockquote><h3 id="d9883578b821-·-security-updates-for-friday" tabindex="-1"><code>d9883578b821</code> · <a href="https://lwn.net/Articles/1104174/" target="_blank" rel="noreferrer">Security updates for Friday</a> <a class="header-anchor" href="#d9883578b821-·-security-updates-for-friday" aria-label="Permalink to &quot;`d9883578b821` · [Security updates for Friday](https://lwn.net/Articles/1104174/)&quot;">​</a></h3><p><em>daroc｜lwn</em></p><p>AlmaLinux、Debian 和 Fedora 发布了新一轮安全更新，涵盖 curl、mariadb、nodejs、vlc、wordpress 等大量软件包。这是 LWN 常规的发行版安全更新汇总。</p><blockquote><p><strong>学习价值</strong>：发行版层面的安全公告汇总，对内核学习本身价值不大，可作为生态安全动态的背景信息。</p></blockquote><h3 id="ae6464ee11ce-·-the-linux-7-4-merge-window-is-easily-the-largest-in-kernel-history-1" tabindex="-1"><code>ae6464ee11ce</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Massive-Window" target="_blank" rel="noreferrer">The Linux 7.4 Merge Window Is Easily The Largest In Kernel History</a> <a class="header-anchor" href="#ae6464ee11ce-·-the-linux-7-4-merge-window-is-easily-the-largest-in-kernel-history-1" aria-label="Permalink to &quot;`ae6464ee11ce` · [The Linux 7.4 Merge Window Is Easily The Largest In Kernel History](https://www.phoronix.com/news/Linux-7.4-Massive-Window)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 的 merge window 成为内核历史上规模最大的一次，文章通过与过去 15 年各主要版本的对比数据加以说明。作者指出近期提交量的明显上升可能与 AI/LLM 辅助开发活动的增加有关。</p><blockquote><p><strong>学习价值</strong>：从宏观统计视角观察内核开发节奏与 AI 对开发流程的影响，有助于理解社区演进趋势。</p></blockquote><h3 id="dff95e4de07f-·-overlayfs-sees-many-fixes-thanks-to-ai-code-review" tabindex="-1"><code>dff95e4de07f</code> · <a href="https://www.phoronix.com/news/OverlayFS-Many-Fixes" target="_blank" rel="noreferrer">OverlayFS Sees Many Fixes Thanks To AI Code Review</a> <a class="header-anchor" href="#dff95e4de07f-·-overlayfs-sees-many-fixes-thanks-to-ai-code-review" aria-label="Permalink to &quot;`dff95e4de07f` · [OverlayFS Sees Many Fixes Thanks To AI Code Review](https://www.phoronix.com/news/OverlayFS-Many-Fixes)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 合入了一批 OverlayFS 修复，并且这些修复计划 backport 到当前 stable 内核版本。这些修复得益于 AI 代码审查（AI code review）发现的问题。</p><blockquote><p><strong>学习价值</strong>：OverlayFS 是 Linux 联合挂载文件系统的核心实现，关注其修复历史是学习 VFS 与 union mount 机制的实用途径。</p></blockquote><h3 id="_4ced3ebd9886-·-ai-use-in-the-linux-kernel-microsoft-defender-on-linux-other-october-highlights" tabindex="-1"><code>4ced3ebd9886</code> · <a href="https://www.phoronix.com/news/October-2026-Highlights" target="_blank" rel="noreferrer">AI Use In The Linux Kernel, Microsoft Defender On Linux &amp; Other October Highlights</a> <a class="header-anchor" href="#_4ced3ebd9886-·-ai-use-in-the-linux-kernel-microsoft-defender-on-linux-other-october-highlights" aria-label="Permalink to &quot;`4ced3ebd9886` · [AI Use In The Linux Kernel, Microsoft Defender On Linux &amp; Other October Highlights](https://www.phoronix.com/news/October-2026-Highlights)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>十月亮点回顾包括 Linux 7.3、Ubuntu 26.10 和 KDE Plasma 6.8 的发布。AI/LLM 在内核开发中的使用日益增多引发讨论，而 Microsoft 将 Defender 引入 Linux 桌面则是最大意外。</p><blockquote><p><strong>学习价值</strong>：作为月度新闻汇总，可快速了解内核社区与开源生态的整体动向，但技术深度有限。</p></blockquote><h3 id="_4545fcc807c7-·-linux-7-4-merge-window-saw-nearly-20k-commits-source-tree-approaching-42-million-lines" tabindex="-1"><code>4545fcc807c7</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Merge-Window" target="_blank" rel="noreferrer">Linux 7.4 Merge Window Saw Nearly 20k Commits, Source Tree Approaching 42 Million Lines</a> <a class="header-anchor" href="#_4545fcc807c7-·-linux-7-4-merge-window-saw-nearly-20k-commits-source-tree-approaching-42-million-lines" aria-label="Permalink to &quot;`4545fcc807c7` · [Linux 7.4 Merge Window Saw Nearly 20k Commits, Source Tree Approaching 42 Million Lines](https://www.phoronix.com/news/Linux-7.4-Merge-Window)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4 merge window 收到近 2 万次 commit，创下历史纪录，内核源码树总行数正逼近 4200 万行（7.3 发布时为约 4102 万行）。以 Git commit 数量衡量，这是有记录以来最繁忙的 merge window。</p><blockquote><p><strong>学习价值</strong>：通过 cloc 和 git 统计数据观察内核规模增长，对理解项目体量与开发活跃度有参考价值。</p></blockquote><h3 id="_043a04b116af-·-brief-server-downtime-expected-tonight" tabindex="-1"><code>043a04b116af</code> · <a href="https://www.phoronix.com/news/RAID-Drive-Replacement-Tonight" target="_blank" rel="noreferrer">Brief Server Downtime Expected Tonight</a> <a class="header-anchor" href="#_043a04b116af-·-brief-server-downtime-expected-tonight" aria-label="Permalink to &quot;`043a04b116af` · [Brief Server Downtime Expected Tonight](https://www.phoronix.com/news/RAID-Drive-Replacement-Tonight)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Phoronix.com 及关联站点将于 11 月 1 日午夜 PST 短暂停机，原因是 NVMe SSD RAID 阵列中一块硬盘故障需要更换。</p><blockquote><p><strong>学习价值</strong>：与内核学习无关，仅为站点运维通知。</p></blockquote><h3 id="_6ef4b277ba96-·-openshot-4-1-released-with-auto-optimize-cli-automation-arm64-linux-builds" tabindex="-1"><code>6ef4b277ba96</code> · <a href="https://www.phoronix.com/news/OpenShot-4.1-Released" target="_blank" rel="noreferrer">OpenShot 4.1 Released With Auto-Optimize, CLI Automation &amp; ARM64 Linux Builds</a> <a class="header-anchor" href="#_6ef4b277ba96-·-openshot-4-1-released-with-auto-optimize-cli-automation-arm64-linux-builds" aria-label="Permalink to &quot;`6ef4b277ba96` · [OpenShot 4.1 Released With Auto-Optimize, CLI Automation &amp; ARM64 Linux Builds](https://www.phoronix.com/news/OpenShot-4.1-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>开源视频编辑软件 OpenShot 发布 4.1 大版本更新，新增自动优化（auto-optimize）、CLI 自动化功能以及 ARM64 Linux 构建支持。</p><blockquote><p><strong>学习价值</strong>：用户态应用新闻，与内核学习无关。</p></blockquote><h3 id="_14e93ef769e4-·-enlightenment-0-28-released-with-many-improvements" tabindex="-1"><code>14e93ef769e4</code> · <a href="https://www.phoronix.com/news/Enlightenment-0.28" target="_blank" rel="noreferrer">Enlightenment 0.28 Released With Many Improvements</a> <a class="header-anchor" href="#_14e93ef769e4-·-enlightenment-0-28-released-with-many-improvements" aria-label="Permalink to &quot;`14e93ef769e4` · [Enlightenment 0.28 Released With Many Improvements](https://www.phoronix.com/news/Enlightenment-0.28)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Enlightenment 0.28 于万圣节发布，距上一版本 0.27 已近两年，累积了大量改进，打破了其约 12 个月的发布节奏。</p><blockquote><p><strong>学习价值</strong>：桌面环境发布新闻，与内核学习无关。</p></blockquote><h3 id="_9628066f60fb-·-linux-mint-developing-new-apps-for-terminal-system-monitoring" tabindex="-1"><code>9628066f60fb</code> · <a href="https://www.phoronix.com/news/Linux-Mint-October-2026" target="_blank" rel="noreferrer">Linux Mint Developing New Apps For Terminal &amp; System Monitoring</a> <a class="header-anchor" href="#_9628066f60fb-·-linux-mint-developing-new-apps-for-terminal-system-monitoring" aria-label="Permalink to &quot;`9628066f60fb` · [Linux Mint Developing New Apps For Terminal &amp; System Monitoring](https://www.phoronix.com/news/Linux-Mint-October-2026)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux Mint 发布 2026 年 10 月状态报告，介绍了在 Linux Mint 27 稳定版（预计圣诞节前后发布）之前正在进行的各项开发工作，包括新的终端和系统监控应用。这些属于发行版层面的用户空间工具开发，与内核本身关系不大。</p><blockquote><p><strong>学习价值</strong>：对内核学习者价值有限，可作为了解发行版生态动态的背景信息。</p></blockquote><h3 id="f0636f3c5ff7-·-new-linux-7-4-feature-for-reducing-ai-noise-already-reverted-due-to-a-crazy-beast" tabindex="-1"><code>f0636f3c5ff7</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Drops-Taint-Bind" target="_blank" rel="noreferrer">New Linux 7.4 Feature For Reducing AI Noise Already Reverted Due To A &quot;Crazy Beast&quot;</a> <a class="header-anchor" href="#f0636f3c5ff7-·-new-linux-7-4-feature-for-reducing-ai-noise-already-reverted-due-to-a-crazy-beast" aria-label="Permalink to &quot;`f0636f3c5ff7` · [New Linux 7.4 Feature For Reducing AI Noise Already Reverted Due To A &quot;Crazy Beast&quot;](https://www.phoronix.com/news/Linux-7.4-Drops-Taint-Bind)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>上周合入 Linux 7.4 的一个旨在减少 AI/LLM 生成的无效/无关测试配置噪音的新特性已被 revert，原因是 VFIO 子系统中出现了开发者所称的 &quot;crazy beast&quot; 问题。这展示了内核开发中特性合并后被快速回退的常见流程。</p><blockquote><p><strong>学习价值</strong>：提醒学习者关注 merge window 后的 revert 机制，以及 VFIO 子系统的复杂性，是理解内核开发流程的好案例。</p></blockquote><h3 id="ba09db7f0ed5-·-ceph-in-linux-7-4-adds-global-mount-option-for-lazy-i-o" tabindex="-1"><code>ba09db7f0ed5</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Ceph" target="_blank" rel="noreferrer">Ceph In Linux 7.4 Adds Global Mount Option For Lazy I/O</a> <a class="header-anchor" href="#ba09db7f0ed5-·-ceph-in-linux-7-4-adds-global-mount-option-for-lazy-i-o" aria-label="Permalink to &quot;`ba09db7f0ed5` · [Ceph In Linux 7.4 Adds Global Mount Option For Lazy I/O](https://www.phoronix.com/news/Linux-7.4-Ceph)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Ceph 内核客户端的更新已提交至 Linux 7.4，新增了全局 mount 选项以支持 lazy I/O。Ceph 客户端代码位于内核 fs/ceph 目录，是分布式文件系统在内核中的实现之一。</p><blockquote><p><strong>学习价值</strong>：适合学习内核中分布式文件系统客户端的实现，以及 mount 选项如何影响 I/O 路径行为。</p></blockquote><h3 id="_74a817dffaf9-·-gnome-now-has-an-established-rfc-process-gnome-os-continues-improving" tabindex="-1"><code>74a817dffaf9</code> · <a href="https://www.phoronix.com/news/GNOME-Establishes-RFC" target="_blank" rel="noreferrer">GNOME Now Has An Established RFC Process, GNOME OS Continues Improving</a> <a class="header-anchor" href="#_74a817dffaf9-·-gnome-now-has-an-established-rfc-process-gnome-os-continues-improving" aria-label="Permalink to &quot;`74a817dffaf9` · [GNOME Now Has An Established RFC Process, GNOME OS Continues Improving](https://www.phoronix.com/news/GNOME-Establishes-RFC)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>GNOME 社区就正式的 RFC（Request for Comments）流程达成共识，用于解决重大技术问题和架构变更，取代以往临时性的讨论方式。同时 GNOME OS 也在持续改进中。</p><blockquote><p><strong>学习价值</strong>：对内核学习价值有限，但 RFC 流程与 Linux 内核的 RFC 机制有可比之处，可作参考。</p></blockquote><h3 id="_298084a725cc-·-dxvk-nvapi-0-9-3-brings-nice-improvements-for-linux-gamers-on-latest-nvidia-drivers" tabindex="-1"><code>298084a725cc</code> · <a href="https://www.phoronix.com/news/DXVK-NVAPI-0.9.3" target="_blank" rel="noreferrer">DXVK-NVAPI 0.9.3 Brings Nice Improvements For Linux Gamers On Latest NVIDIA Drivers</a> <a class="header-anchor" href="#_298084a725cc-·-dxvk-nvapi-0-9-3-brings-nice-improvements-for-linux-gamers-on-latest-nvidia-drivers" aria-label="Permalink to &quot;`298084a725cc` · [DXVK-NVAPI 0.9.3 Brings Nice Improvements For Linux Gamers On Latest NVIDIA Drivers](https://www.phoronix.com/news/DXVK-NVAPI-0.9.3)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>DXVK-NVAPI 0.3 发布，这是 Valve 用于 Steam Play/Proton 的 NVIDIA NVAPI 实现，帮助 Windows 游戏在 Linux 上运行时集成 NVIDIA 技术。新版本针对最新 NVIDIA 驱动带来了多项改进。</p><blockquote><p><strong>学习价值</strong>：属于用户空间图形兼容层项目，对内核学习价值有限。</p></blockquote><h3 id="_6083399ca462-·-sculpt-os-26-10-released-now-powered-by-genode-s-custom-microkernel" tabindex="-1"><code>6083399ca462</code> · <a href="https://www.phoronix.com/news/Sculpt-OS-26.10" target="_blank" rel="noreferrer">Sculpt OS 26.10 Released - Now Powered By Genode&#39;s Custom Microkernel</a> <a class="header-anchor" href="#_6083399ca462-·-sculpt-os-26-10-released-now-powered-by-genode-s-custom-microkernel" aria-label="Permalink to &quot;`6083399ca462` · [Sculpt OS 26.10 Released - Now Powered By Genode&#39;s Custom Microkernel](https://www.phoronix.com/news/Sculpt-OS-26.10)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>基于 Genode 框架的通用操作系统 Sculpt OS 发布 26.10 版本，现在改用 Genode 项目自研的 microkernel，而非第三方内核。这体现了 microkernel 架构操作系统的一种独立演进路线。</p><blockquote><p><strong>学习价值</strong>：虽非 Linux 内核内容，但可作为对比 monolithic kernel 与 microkernel 设计的参考案例。</p></blockquote><h3 id="_8bd5bd943cc3-·-postgresql-19-running-behind-schedule-due-to-ai-llm-burden" tabindex="-1"><code>8bd5bd943cc3</code> · <a href="https://www.phoronix.com/news/PostgreSQL-19-Late" target="_blank" rel="noreferrer">PostgreSQL 19 Running Behind Schedule Due To AI/LLM Burden</a> <a class="header-anchor" href="#_8bd5bd943cc3-·-postgresql-19-running-behind-schedule-due-to-ai-llm-burden" aria-label="Permalink to &quot;`8bd5bd943cc3` · [PostgreSQL 19 Running Behind Schedule Due To AI/LLM Burden](https://www.phoronix.com/news/PostgreSQL-19-Late)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>PostgreSQL 19 的年度特性版本因 AI/LLM 带来的大量低质量 bug 报告和补丁而延期，开发者不堪重负，发布时间从惯常的 9~10 月推迟到至少 11 月。这与 Linux 内核社区面临的 AI 噪音问题相呼应。</p><blockquote><p><strong>学习价值</strong>：反映了 AI 生成内容对开源社区维护流程的冲击，与内核 7.4 中减少 AI 噪音的机制形成对照，值得思考社区治理问题。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>5c97d8672a5b</code> · <a href="https://lwn.net/Articles/1104192/" target="_blank" rel="noreferrer">Remote code execution on Linux systems with multipath TCP</a></li><li><code>8e91cf16d1c7</code> · <a href="https://lore.kernel.org/all/20261101232829.593680-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1 0/2] hrtimer: Add hrtimer_forward_safe_from_callback()</a></li><li><code>6c2ffc1dec26</code> · <a href="https://lore.kernel.org/all/20261102005654.532438-16-pablo@netfilter.org/" target="_blank" rel="noreferrer">[PATCH net 15/15] netfilter: nat: zero newrange before filling it in</a></li></ul>',312)])])}const b=r(n,[["render",l]]);export{h as __pageData,b as default};
